import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Understand rankings and competitions","description":"","frontmatter":{"title":"Understand rankings and competitions","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"en","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1c45cf6e9355092d95dc9f90025b2965e0a6a4cddb453fb25680192ab41e873c","translationRevision":"1c45cf6e9355092d95dc9f90025b2965e0a6a4cddb453fb25680192ab41e873c","order":30},"headers":[],"relativePath":"en/user/points/rankings.md","filePath":"en/user/points/rankings.md","lastUpdated":1795735295000}`),s={name:`en/user/points/rankings.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="understand-rankings-and-competitions" tabindex="-1">Understand rankings and competitions <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to “Understand rankings and competitions”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Choose the appropriate ranked view and recognize the limits of the developing rankings workspace. You need incoming activity for meaningful scores. Start with the ordinary <a href="./rules.html">Points</a> leaderboard or the top-viewer panels in <a href="./../live/feed.html">Live feed</a> when you only need to inspect current viewers.</p><h2 id="use-the-right-view" tabindex="-1">Use the right view <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to “Use the right view”">​</a></h2><ol><li>In <strong>Points</strong>, search for a viewer and sort by points, level or viewer identity. Refresh before comparing a manual adjustment with an award.</li><li>In <strong>Live feed</strong>, inspect the available ranked viewer panels. These can receive ranking-engine snapshots independently of the point balance table.</li><li>For an overlay, open <a href="./../overlays/">Overlays</a>, select the ranking kind and inspect its source options. A configured ranking source must exist before its output can appear.</li></ol><p>The dedicated <strong>Rankings &amp; competitions</strong> workspace is experimental. Its frontend route is <code>#/rankings</code>, but it is deliberately hidden from the main navigation and is not restored as the startup tab. A missing sidebar item does not mean the route or ranking engine has been removed.</p><h2 id="configure-an-experimental-ranking" tabindex="-1">Configure an experimental ranking <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to “Configure an experimental ranking”">​</a></h2><p>If your environment exposes that workspace, start with one creator, one room, grouping by user and a session window. Add one advertised metric, such as <code>tiktok.like</code> / <code>like.count</code>, with weight <code>1</code>. Set a modest result limit and create the definition. The form also supports rolling and daily windows, with explicit duration/event bounds or timezone offset.</p><p>Read the resulting snapshot before introducing additional sources. Pause and resume affect ranking collection; reset intentionally clears ranking state. Competition options and vote-related sources have their own grouping rules. Do not assume a points reset also resets a competition, or that every custom grouping works with every metric.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Expected result and status”">​</a></h2><p>Ordinary leaderboards are available; the dedicated management page remains experimental. Scores come from the host, not from counting displayed feed rows. Real broadcast/OBS acceptance and every competition combination are not established by this guide.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recovery”">​</a></h2><p>Check creator, room, source enablement, window and pause state when scores stay empty. Remove unsupported source/group combinations rather than inventing field names. Preserve important data through <a href="./../preferences/backups.html">backups</a> before resets, and include definition ID and diagnostic code in a report.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Operational details”">​</a></h2><p>The Points table requests 100 viewers and filters/sorts only those received rows. Refreshing or sorting by name does not search the entire database. Feed rankings show 10 rows per creator/room session: gift diamonds for Top and counts for Likes, with tracking bounded to 5,000 viewers. They do not measure saved points. Compare units and session boundaries before comparing totals.</p><p>Try it interactively before touching your real setup:</p>`,16),t(d,{scenario:`points`,locale:`en`,panel:`points`,title:`Try rankings and viewer points`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Command line operations <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Command line operations”">​</a></h2><p>Every operation in this guide is also available from the CLI — offline, scriptable and agent-friendly. Usage lines are parser syntax and stay in English in every locale.</p><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>list ranking definitions</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>metrics available to ranking definitions</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>create a ranking definition</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>update a ranking definition</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>read one ranking</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>current standings of one ranking</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>delete a ranking <strong>destructive</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>reset accumulated state <strong>destructive</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>pause accumulation</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>resume accumulation</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>add an external contribution</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>list competitions</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>read one competition</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>create a competition</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>update a competition</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>delete a competition <strong>destructive</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>current competition state</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>final or intermediate results</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>record a competition action</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>flag an action as uncertain</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>resolve an uncertain action</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>start a competition</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>finish a competition <strong>destructive</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>winner candidates</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>select the winner</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>pause a competition</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>resume a competition</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>cancel a competition <strong>destructive</strong></td></tr></tbody></table><p>See the <a href="./../../developer/cli.html">full command reference</a> for conventions, JSON output and destructive-operation markers.</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};